import type { Article } from "../curriculumTypes";

export const ARTICLES: Article[] = [{"id":"art_xx_01","moduleId":"MODULE_XX_APPRECIATION","title":"长恨歌","subtitle":null,"author":"白居易","dynasty":"唐代","genre":"歌行","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"汉皇重色思倾国，御宇多年求不得。杨家有女初长成，养在深闺人未识。天生丽质难自弃，一朝选在君王侧。回眸一笑百媚生，六宫粉黛无颜色\n春寒赐浴华清池，温泉水滑洗凝脂。侍儿扶起娇无力，始是新承恩泽时\n后宫佳丽三千人，三千宠爱在一身\n渔阳鼙鼓动地来，惊破霓裳羽衣曲。九重城阙烟尘生，千乘万骑西南行\n六军不发无奈何，宛转蛾眉马前死。花钿委地无人收，翠翘金雀玉搔头\n行宫见月伤心色，夜雨闻铃肠断声\n天旋日转回龙驭，到此踌躇不能去。马嵬坡下泥土中，不见玉颜空死处\n在天愿作比翼鸟，在地愿为连理枝。天长地久有时尽，此恨绵绵无绝期。","paragraphs":["回眸一笑百媚生，六宫粉黛无颜色。","在天愿作比翼鸟，在地愿为连理枝。天长地久有时尽，此恨绵绵无绝期。"],"translation":"唐玄宗好色思求倾国倾城的美人。","annotations":["比翼鸟连理枝：至死不渝的爱情誓言。"],"sortOrder":1,"totalSegments":10,"totalCards":10},{"id":"art_xx_02","moduleId":"MODULE_XX_APPRECIATION","title":"湘夫人","subtitle":null,"author":"屈原","dynasty":"战国·楚","genre":"辞赋","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"帝子降兮北渚，目眇眇兮愁予。袅袅兮秋风，洞庭波兮木叶下。登白薠兮骋望，与佳期兮夕张。鸟何萃兮苹中，罾何为兮木上？沅有芷兮澧有兰，思公子兮未敢言。荒忽兮远望，观流水兮潺湲。","paragraphs":["袅袅兮秋风，洞庭波兮木叶下。沅有芷兮澧有兰，思公子兮未敢言。"],"translation":"湘夫人降临在江北的小洲上，远望双眼迷茫使我心怀忧伤。","annotations":["袅袅秋风洞庭木叶下：千古秋景发端。"],"sortOrder":2,"totalSegments":3,"totalCards":3},{"id":"art_xx_03","moduleId":"MODULE_XX_APPRECIATION","title":"咏怀八十二首·其一","subtitle":"其一","author":"阮籍","dynasty":"魏晋","genre":"诗","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"夜中不能寐，起坐弹鸣琴。薄帷鉴明月，清风吹我襟。孤鸿号外野，翔鸟鸣北林。徘徊将何见？忧思独伤心。","paragraphs":["夜中不能寐，起坐弹鸣琴。薄帷鉴明月，清风吹我襟。徘徊将何见？忧思独伤心。"],"translation":"夜半深沉无法入眠，起身坐下弹响古琴。","annotations":["薄帷鉴明月：明月穿透薄帷映照。"],"sortOrder":3,"totalSegments":2,"totalCards":2},{"id":"art_xx_04","moduleId":"MODULE_XX_APPRECIATION","title":"杂诗十二首·其二","subtitle":"其二","author":"陶渊明","dynasty":"东晋","genre":"诗","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"白日沦西阿，素月出东岭。遥遥万里晖，荡荡空中景。风来入房户，夜中枕席冷。气变悟时易，不眠知夕永。欲言无予和，挥杯劝孤影。日月掷人去，有志不获骋。念此怀悲凄，终晓不能静。","paragraphs":["日月掷人去，有志不获骋。念此怀悲凄，终晓不能静。"],"translation":"太阳落入西方山坳，明月升起在东岭之上。","annotations":["日月掷人去：岁月如飞掷般无情抛弃人。"],"sortOrder":4,"totalSegments":2,"totalCards":2},{"id":"art_xx_05","moduleId":"MODULE_XX_APPRECIATION","title":"越中览古","subtitle":null,"author":"李白","dynasty":"唐代","genre":"诗","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"越王勾践破吴归，义士还乡尽锦衣。宫女如花满春殿，只今惟有鹧鸪飞。","paragraphs":["越王勾践破吴归，义士还乡尽锦衣。宫女如花满春殿，只今惟有鹧鸪飞。"],"translation":"越王勾践灭亡吴国胜利归来，战士们衣锦还乡风光无限。","annotations":["只今惟有鹧鸪飞：历史兴亡的盛衰之叹。"],"sortOrder":5,"totalSegments":2,"totalCards":2},{"id":"art_xx_06","moduleId":"MODULE_XX_APPRECIATION","title":"一剪梅·红藕香残玉簟秋","subtitle":null,"author":"李清照","dynasty":"宋代","genre":"词","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"红藕香残玉簟秋。轻解罗裳，独上兰舟。云中谁寄锦书来，雁字回时，月满西楼。\n花自飘零水自流。一种相思，两处闲愁。此情无计可消除，才下眉头，却上心头。","paragraphs":["红藕香残玉簟秋。轻解罗裳，独上兰舟。云中谁寄锦书来，雁字回时，月满西楼。","花自飘零水自流。一种相思，两处闲愁。此情无计可消除，才下眉头，却上心头。"],"translation":"荷花凋谢香气消尽，竹席透出阵阵秋凉。","annotations":["才下眉头却上心头：化抽象相思为具象体验。"],"sortOrder":6,"totalSegments":4,"totalCards":4},{"id":"art_xx_07","moduleId":"MODULE_XX_APPRECIATION","title":"今别离·其一","subtitle":"其一","author":"黄遵宪","dynasty":"清末","genre":"诗","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"别肠转如轮，一刻不相释。何意万里行，坐使秋夕隔？火轮驰骤如飞电，千重山岳瞬息变。","paragraphs":["别肠转如轮，一刻不相释。何意万里行，坐使秋夕隔？"],"translation":"离别的心肠如车轮般辗转翻覆，片刻也不能排解。","annotations":["火轮驰骤：近代蒸汽火车与汽船。"],"sortOrder":7,"totalSegments":2,"totalCards":2},{"id":"art_xx_08","moduleId":"MODULE_XX_APPRECIATION","title":"夜归鹿门山歌","subtitle":null,"author":"孟浩然","dynasty":"唐代","genre":"诗","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"山寺钟鸣昼已昏，渔梁渡头争渡喧。人随沙岸向江村，余亦乘舟归鹿门。鹿门月照开烟树，忽到庞公栖隐处。岩扉松径长寂寥，惟有幽人自来去。","paragraphs":["山寺钟鸣昼已昏，渔梁渡头争渡喧。","岩扉松径长寂寥，惟有幽人自来去。"],"translation":"山寺传来钟声天色已近黄昏，渔梁渡口争相渡河喧闹一片。","annotations":["庞公：汉末隐士庞德公。"],"sortOrder":8,"totalSegments":3,"totalCards":3},{"id":"art_xx_09","moduleId":"MODULE_XX_APPRECIATION","title":"登岳阳楼","subtitle":null,"author":"杜甫","dynasty":"唐代","genre":"诗","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"昔闻洞庭水，今上岳阳楼。吴楚东南坼，乾坤日夜浮。亲朋无一字，老病有孤舟。戎马关山北，凭轩涕泗流。","paragraphs":["昔闻洞庭水，今上岳阳楼。吴楚东南坼，乾坤日夜浮。亲朋无一字，老病有孤舟。戎马关山北，凭轩涕泗流。"],"translation":"早闻洞庭盛名，今登岳阳名楼。","annotations":["乾坤日夜浮：天水交融日夜沉浮。"],"sortOrder":9,"totalSegments":4,"totalCards":4},{"id":"art_xx_10","moduleId":"MODULE_XX_APPRECIATION","title":"菩萨蛮·其二","subtitle":"其二","author":"韦庄","dynasty":"五代","genre":"词","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"人人尽说江南好，游人只合江南老。春水碧于天，画船听雨眠。垆边人似月，皓腕凝霜雪。未老莫还乡，还乡须断肠。","paragraphs":["人人尽说江南好，游人只合江南老。春水碧于天，画船听雨眠。","垆边人似月，皓腕凝霜雪。未老莫还乡，还乡须断肠。"],"translation":"人人都说江南好，漂泊的游人只该在江南终老。","annotations":["春水碧于天画船听雨眠：极写江南之柔美安适。"],"sortOrder":10,"totalSegments":3,"totalCards":3},{"id":"art_xx_11","moduleId":"MODULE_XX_APPRECIATION","title":"积雨辋川庄作","subtitle":null,"author":"王维","dynasty":"唐代","genre":"诗","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"积雨空林烟火迟，蒸藜炊黍饷东菑。漠漠水田飞白鹭，阴阴夏木啭黄鹂。山中习静朝观槿，松下清斋折露葵。野老与人争席罢，海鸥何事更相疑。","paragraphs":["积雨空林烟火迟，蒸藜炊黍饷东菑。漠漠水田飞白鹭，阴阴夏木啭黄鹂。"],"translation":"连绵阴雨笼罩空林，炊烟升起迟缓。","annotations":["漠漠水田飞白鹭阴阴夏木啭黄鹂：千古写景名联。"],"sortOrder":11,"totalSegments":4,"totalCards":4},{"id":"art_xx_12","moduleId":"MODULE_XX_APPRECIATION","title":"旅夜书怀","subtitle":null,"author":"杜甫","dynasty":"唐代","genre":"诗","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"细草微风岸，危樯独夜舟。星垂平野阔，月涌大江流。名岂文章著，官应老病休。飘飘何所似，天地一沙鸥。","paragraphs":["细草微风岸，危樯独夜舟。星垂平野阔，月涌大江流。","飘飘何所似，天地一沙鸥。"],"translation":"微风吹拂着江岸上的细草，高耸桅杆的孤舟在黑夜中停泊。","annotations":["星垂平野阔月涌大江流：壮阔与孤独的极致融合。"],"sortOrder":12,"totalSegments":4,"totalCards":4},{"id":"art_xx_13","moduleId":"MODULE_XX_APPRECIATION","title":"新城道中·其一","subtitle":"其一","author":"苏轼","dynasty":"宋代","genre":"诗","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"东风知我欲山行，吹断檐间积雨声。岭上晴云披絮帽，树头初日挂铜钲。野桃含笑竹篱短，溪柳自摇沙水清。西崦人家应最乐，煮芹烧笋饷春耕。","paragraphs":["东风知我欲山行，吹断檐间积雨声。","野桃含笑竹篱短，溪柳自摇沙水清。西崦人家应最乐，煮芹烧笋饷春耕。"],"translation":"春天的东风好像知道我要去山间行走，吹散了屋檐连绵的积雨声。","annotations":["野桃含笑溪柳自摇：生动传神描摹春光。"],"sortOrder":13,"totalSegments":4,"totalCards":4},{"id":"art_xx_14","moduleId":"MODULE_XX_APPRECIATION","title":"阁夜","subtitle":null,"author":"杜甫","dynasty":"唐代","genre":"诗","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"岁暮阴阳催短景，天涯霜雪霁寒宵。五更鼓角声悲壮，三峡星河影动摇。野哭千家闻战伐，夷歌数处起渔樵。卧龙跃马终黄土，人事音书漫寂寥。","paragraphs":["岁暮阴阳催短景，天涯霜雪霁寒宵。五更鼓角声悲壮，三峡星河影动摇。","卧龙跃马终黄土，人事音书漫寂寥。"],"translation":"岁末严冬日光渐短，流落天涯霜雪初晴寒夜森森。","annotations":["卧龙跃马终黄土：英雄终归黄土之叹。"],"sortOrder":14,"totalSegments":4,"totalCards":4},{"id":"art_xx_15","moduleId":"MODULE_XX_APPRECIATION","title":"苏幕遮·燎沉香","subtitle":null,"author":"周邦彦","dynasty":"宋代","genre":"词","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"燎沉香，消溽暑。鸟雀呼晴，侵晓窥檐语。叶上初阳干宿雨，水面清圆，一一风荷举。\n故乡遥，何日去？家住吴门，久作长安旅。五月渔郎相忆否？小楫轻舟，梦入芙蓉浦。","paragraphs":["叶上初阳干宿雨，水面清圆，一一风荷举。","故乡遥，何日去？小楫轻舟，梦入芙蓉浦。"],"translation":"点燃沉香消解潮热的暑气，鸟雀欢叫天晴。","annotations":["水面清圆一一风荷举：王国维评真能得荷之神理者。"],"sortOrder":15,"totalSegments":4,"totalCards":4},{"id":"art_xx_16","moduleId":"MODULE_XX_APPRECIATION","title":"国殇","subtitle":null,"author":"屈原","dynasty":"战国·楚","genre":"辞赋","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"操吴戈兮被犀甲，车错毂兮短兵接。旌蔽日兮敌若云，矢交坠兮士争先。凌余阵兮躐余行，左骖殪兮右刃伤。霾两轮兮絷四马，援玉枹兮击鸣鼓。天时怼兮威灵怒，严杀尽兮弃原野。\n出不入兮往不反，平原忽兮路超远。带长剑兮挟秦弓，首身离兮心不惩。诚既勇兮又以武，终刚强兮不可凌。身既死兮神以灵，魂魄毅兮为鬼雄！","paragraphs":["诚既勇兮又以武，终刚强兮不可凌。身既死兮神以灵，魂魄毅兮为鬼雄！"],"translation":"手执吴戈身穿犀甲，战车相错短兵相接。","annotations":["生当作人杰死亦为鬼雄之渊薮。"],"sortOrder":16,"totalSegments":4,"totalCards":4},{"id":"art_xx_17","moduleId":"MODULE_XX_APPRECIATION","title":"登柳州城楼寄漳汀封连四州","subtitle":null,"author":"柳宗元","dynasty":"唐代","genre":"诗","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"城上高楼接大荒，海天愁思正茫茫。惊风乱飐芙蓉水，密雨斜侵薜荔墙。岭树重遮千里目，江流曲似九回肠。共来百越文身地，犹自各在天一方。","paragraphs":["城上高楼接大荒，海天愁思正茫茫。惊风乱飐芙蓉水，密雨斜侵薜荔墙。岭树重遮千里目，江流曲似九回肠。"],"translation":"登上高耸城楼连接广袤荒野，海天相接处愁绪正茫茫一片。","annotations":["岭树重遮千里目江流曲似九回肠：借景抒发贬谪幽愤。"],"sortOrder":17,"totalSegments":4,"totalCards":4},{"id":"art_xx_18","moduleId":"MODULE_XX_APPRECIATION","title":"菩萨蛮·小山重叠金明灭","subtitle":null,"author":"温庭筠","dynasty":"唐代","genre":"词","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"小山重叠金明灭，鬓云欲度香腮雪。懒起画蛾眉，弄妆梳洗迟。\n照花前后镜，花面交相映。新帖绣罗襦，双双金鹧鸪。","paragraphs":["小山重叠金明灭，鬓云欲度香腮雪。懒起画蛾眉，弄妆梳洗迟。","新帖绣罗襦，双双金鹧鸪。"],"translation":"眉山小重山金光闪耀忽明忽灭，乌黑鬓发拂过雪白香腮。","annotations":["双双金鹧鸪：以双双反衬孤独寂寞。"],"sortOrder":18,"totalSegments":3,"totalCards":3},{"id":"art_xx_19","moduleId":"MODULE_XX_APPRECIATION","title":"般涉调·哨遍·高祖还乡","subtitle":null,"author":"睢景臣","dynasty":"元代","genre":"散文","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"社长排门告示，但有的差使无推故。这家推为头，那家教办具。正慌乱，官报汉高皇过故乡，各备供张。","paragraphs":["社长排门告示，但有的差使无推故。"],"translation":"里长挨家挨户通知，凡有差使不得借故推托。","annotations":["元散曲名篇讽刺帝王还乡阵仗。"],"sortOrder":19,"totalSegments":2,"totalCards":2},{"id":"art_xx_20","moduleId":"MODULE_XX_APPRECIATION","title":"过小孤山大孤山","subtitle":null,"author":"陆游","dynasty":"宋代","genre":"散文","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"八月一日，过同安县。舟行江中，自淮南视江南，皆绝壁。至小孤，岸愈奇，山峰拔地起，亭亭孤峙，高插云霄。","paragraphs":["舟行江中，自淮南视江南，皆绝壁。至小孤，岸愈奇，山峰拔地起，亭亭孤峙，高插云霄。"],"translation":"八月初一，经过同安县。","annotations":["小孤山大孤山：长江胜景。"],"sortOrder":20,"totalSegments":3,"totalCards":3},{"id":"art_xx_21","moduleId":"MODULE_XX_APPRECIATION","title":"项羽之死","subtitle":null,"author":"司马迁","dynasty":"西汉","genre":"散文","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"项王军壁垓下，兵少食尽，汉军及诸侯兵围之数重。夜闻汉军四面皆楚歌，项王乃大惊曰：“汉皆已得楚乎？是何楚人之多也！”项王则夜起，饮帐中。有美人名虞，常幸从；骏马名骓，常骑之。于是项王乃悲歌慷慨，自为诗曰：“力拔山兮气盖世！时不利兮骓不逝！骓不逝兮可奈何！虞兮虞兮奈若何！”歌数阕，美人和之。项王泣数行下，左右皆泣，莫能仰视。\n项王乃复引兵而东，至东城，乃有二十八骑。汉骑追者数千人。项王自度不得脱。谓其骑曰：“吾起兵至今八岁矣，身七十余战，所当者破，所击者服，未尝败北，遂霸有天下。然今卒困于此，此天之亡我，非战之罪也。今日固决死，愿为诸君决战，必三胜之，为诸君溃围，斩将，刈旗，令诸君知天亡我，非战之罪也。”乃分其骑以为四队，四向。\n项王乃引兵西沮，汉骑司马吕马童相烦，项王曰：“吾闻汉购我头千金，邑万户，吾为若德。”乃自刎而死。","paragraphs":["项王军壁垓下，兵少食尽，汉军及诸侯兵围之数重。夜闻汉军四面皆楚歌，项王乃大惊曰：“汉皆已得楚乎？是何楚人之多也！”","项王则夜起，饮帐中。有美人名虞，常幸从；骏马名骓，常骑之。于是项王乃悲歌慷慨，自为诗曰：“力拔山兮气盖世！时不利兮骓不逝！骓不逝兮可奈何！虞兮虞兮奈若何！”","歌数阕，美人和之。项王泣数行下，左右皆泣，莫能仰视。","项王自度不得脱。谓其骑曰：“吾起兵至今八岁矣，身七十余战，所当者破，所击者服，未尝败北，遂霸有天下。然今卒困于此，此天之亡我，非战之罪也。”","今日固决死，愿为诸君决战，必三胜之，为诸君溃围，斩将，刈旗，令诸君知天亡我，非战之罪也。","项王乃引兵西沮，汉骑司马吕马童相烦，项王曰：“吾闻汉购我头千金，邑万户，吾为若德。”乃自刎而死。"],"translation":"项羽的军队在垓下筑垒防御，兵力衰竭粮食断绝。","annotations":["四面楚歌：四面受敌，孤立无援之境地。","霸王别姬：英雄末路泣下相别。"],"sortOrder":21,"totalSegments":6,"totalCards":6},{"id":"art_xx_22","moduleId":"MODULE_XX_APPRECIATION","title":"方山子传","subtitle":null,"author":"苏轼","dynasty":"宋代","genre":"散文","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"方山子，光、黄间隐人也。少时慕朱家、郭解为人，闾里之侠皆宗之。稍壮，折节读书，欲以此驰骋当世，然终不遇。晚乃遁于光、黄间，曰岐亭。庵居蔬食，不与世相闻。弃车马，毁冠服，徒步往来山中，人莫识也。见其所著帽，方耸而高，曰：“此岂古之方山冠之遗像乎？”因谓之方山子。","paragraphs":["方山子，光、黄间隐人也。折节读书，欲以此驰骋当世，然终不遇。晚乃遁于光、黄间。"],"translation":"方山子，是光州、黄州一带的隐士。","annotations":["折节读书：改变旧行致力苦读。"],"sortOrder":22,"totalSegments":3,"totalCards":3},{"id":"art_xx_23","moduleId":"MODULE_XX_APPRECIATION","title":"大铁椎传","subtitle":null,"author":"魏禧","dynasty":"清代","genre":"散文","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"大铁椎，不知何许人。北平陈子灿省兄河南，与客田秀之同宿竦子祠下。夜半，客惊起，见一人貌甚奇，长丈余，手持四十斤铁椎。","paragraphs":["大铁椎，不知何许人。手持四十斤铁椎，奋击如飞。"],"translation":"大铁椎，不知道是什么地方的人。","annotations":["任侠好义之遗风。"],"sortOrder":23,"totalSegments":3,"totalCards":3},{"id":"art_xx_24","moduleId":"MODULE_XX_APPRECIATION","title":"祭十二郎文","subtitle":null,"author":"韩愈","dynasty":"唐代","genre":"散文","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"年、月、日，季父愈闻汝丧之七日，乃能衔哀致诚，使建中远具时羞之奠，告汝十二郎之灵：呜呼！吾少孤，及长，不省所怙，惟兄嫂是依。中年兄殁南方，吾与汝俱幼，从嫂归葬河阳。既又与汝就食江南，零丁孤苦，未尝一日相离也。吾上有三兄，皆不幸早世。承先人后者，在孙惟汝，在子惟吾。两世一身，形单影只。嫂尝抚汝指吾而言曰：“韩氏两世，惟此而已！”汝时尤小，当不复记忆；吾时虽能记忆，亦未知其言之悲也\n呜呼！言有穷而情不可终，汝其知也邪？其不知也邪？呜呼哀哉！尚飨！","paragraphs":["呜呼！吾少孤，及长，不省所怙，惟兄嫂是依。承先人后者，在孙惟汝，在子惟吾。两世一身，形单影只。","呜呼！言有穷而情不可终，汝其知也邪？其不知也邪？呜呼哀哉！"],"translation":"叔父韩愈在听到你去世的第七天，才能够含着悲哀。","annotations":["两世一身形单影只：极言两代亲人零落孤单。"],"sortOrder":24,"totalSegments":6,"totalCards":6},{"id":"art_xx_25","moduleId":"MODULE_XX_APPRECIATION","title":"狱中杂记","subtitle":null,"author":"方苞","dynasty":"清代","genre":"散文","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"康熙四十八年，余在刑部狱，见狱中事有大异于世者。凡被逮受审者，先入禁房，其求钱之术巧诈百出。","paragraphs":["情伪微暧，其能自告？哀鳏寡孤独之民，莫知控诉。"],"translation":"康熙四十八年，我在刑部大狱中。","annotations":["揭露清代牢狱弊端。"],"sortOrder":25,"totalSegments":3,"totalCards":3},{"id":"art_xx_26","moduleId":"MODULE_XX_APPRECIATION","title":"陶庵梦忆序","subtitle":null,"author":"张岱","dynasty":"明末清初","genre":"散文","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"陶庵国破家亡，无所归止，披发入山，骇骇为野人。故书其少时声色犬马之娱，以见往事如梦。","paragraphs":["陶庵国破家亡，无所归止，披发入山。往昔豪华，皆成幻泡。"],"translation":"张岱经历了国破家亡，无处投奔。","annotations":["繁华过眼皆为虚妄。"],"sortOrder":26,"totalSegments":2,"totalCards":2},{"id":"art_xx_27","moduleId":"MODULE_XX_APPRECIATION","title":"春夜宴从弟桃花园序","subtitle":null,"author":"李白","dynasty":"唐代","genre":"散文","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"夫天地者，万物之逆旅也；光阴者，百代之过客也。而浮生若梦，为欢几何？古人秉烛夜游，良有以也。况阳春召我以烟景，大块假我以文章。会桃花之芳园，序天伦之乐事。群季俊秀，皆为惠连；吾人咏歌，独惭康乐。幽赏未已，高谈转清。开琼筵以坐花，飞羽觞而醉月。不有佳咏，何伸雅怀？如诗不成，罚依金谷酒数。","paragraphs":["夫天地者，万物之逆旅也；光阴者，百代之过客也。而浮生若梦，为欢几何？","开琼筵以坐花，飞羽觞而醉月。不有佳咏，何伸雅怀？"],"translation":"天地是万物的客栈，光阴是百代的过客。","annotations":["逆旅：旅店客栈。","飞羽觞而醉月：传递酒杯在月下沉醉。"],"sortOrder":27,"totalSegments":4,"totalCards":4},{"id":"art_xx_28","moduleId":"MODULE_XX_APPRECIATION","title":"游兰溪","subtitle":null,"author":"苏轼","dynasty":"宋代","genre":"散文","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"黄州东南三十里为沙湖，亦曰螺蛳店。予买田其间，因往相田。得疾，闻兰溪僧庞安常善医而聋，往访之。庞善治病，以纸书字问答。","paragraphs":["山下兰芽短浸溪，松间沙路净无泥。谁道人生无再少？门前流水尚能西！休将白发唱黄鸡。"],"translation":"黄州东南三十里是沙湖，去相田时生病访医。","annotations":["门前流水尚能西：自强不息豪迈情怀。"],"sortOrder":28,"totalSegments":2,"totalCards":2},{"id":"art_xx_29","moduleId":"MODULE_XX_APPRECIATION","title":"苦斋记","subtitle":null,"author":"刘基","dynasty":"明代","genre":"散文","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"苦斋者，章溢先生隐居之室也。其地在处州龙泉之青柯山。其居处幽僻，草木之实多苦，故名苦斋。先生乐之，客有问其故者，先生笑曰：‘苦物之感人也深，而使人思者远。’","paragraphs":["苦物之感人也深，而使人思者远。乐生于苦，苦尽甘来。"],"translation":"苦斋是章溢先生隐居的屋室。","annotations":["以苦励志修身。"],"sortOrder":29,"totalSegments":2,"totalCards":2}];
